import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_WIDTH 32
#define THREADS_PER_BLOCK 256 // TILE_WIDTH * TILE_WIDTH / 4
#define THREAD_WORK_SIZE 4

__global__ void matmul_kernel_optimized(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_WIDTH][TILE_WIDTH];
    __shared__ float Bs[TILE_WIDTH][TILE_WIDTH];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;

    int thread_row = tx / (TILE_WIDTH / THREAD_WORK_SIZE);
    int thread_col = tx % (TILE_WIDTH / THREAD_WORK_SIZE);

    int a_row = by * TILE_WIDTH + thread_row;
    int b_col = bx * TILE_WIDTH + thread_col * THREAD_WORK_SIZE;

    float C_values[THREAD_WORK_SIZE] = {0.0f};

    for (int t = 0; t < (N + TILE_WIDTH - 1) / TILE_WIDTH; ++t) {
        // Load tiles into shared memory using vectorized loads
        int a_col = t * TILE_WIDTH + thread_col * THREAD_WORK_SIZE;
        int b_row = t * TILE_WIDTH + thread_row;

        if (a_row < N && a_col < N) {
            ((float4*)As[thread_row])[thread_col] = ((const float4*)A)[(a_row * N + a_col) / 4];
        } else {
            for(int i=0; i<THREAD_WORK_SIZE; ++i) As[thread_row][thread_col*THREAD_WORK_SIZE+i] = 0.0f;
        }

        if (b_row < N && b_col < N) {
           for(int i=0; i<THREAD_WORK_SIZE; ++i)
                if( (b_row + i * (THREADS_PER_BLOCK/ (TILE_WIDTH / THREAD_WORK_SIZE))) < N)
                    Bs[thread_row + i * (THREADS_PER_BLOCK/ (TILE_WIDTH / THREAD_WORK_SIZE)) ][thread_col*THREAD_WORK_SIZE] = B[(b_row + i * (THREADS_PER_BLOCK/ (TILE_WIDTH / THREAD_WORK_SIZE)))* N + b_col];

        } else {
             for(int i=0; i<THREAD_WORK_SIZE; ++i) Bs[thread_row + i * (THREADS_PER_BLOCK/ (TILE_WIDTH / THREAD_WORK_SIZE))][thread_col*THREAD_WORK_SIZE] = 0.0f;
        }


        __syncthreads();

        // Compute partial result using register blocking
        for (int k = 0; k < TILE_WIDTH; ++k) {
            float a_val = As[thread_row][k];
            for(int i=0; i<THREAD_WORK_SIZE; ++i){
                C_values[i] += a_val * Bs[k][thread_col*THREAD_WORK_SIZE+i];
            }
        }

        __syncthreads();
    }

    // Write results to global memory
    int c_row = by * TILE_WIDTH + thread_row;
    int c_col = bx * TILE_WIDTH + thread_col * THREAD_WORK_SIZE;
    if (c_row < N && c_col < N) {
        for(int i=0; i<THREAD_WORK_SIZE; ++i){
            if(c_col+i < N)
             C[c_row * N + c_col+i] = C_values[i];
        }
    }
}


torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions are not compatible for multiplication");

    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    const dim3 threadsPerBlock(THREADS_PER_BLOCK);
    const dim3 numBlocks((N + TILE_WIDTH - 1) / TILE_WIDTH,
                         (N + TILE_WIDTH - 1) / TILE_WIDTH);

    matmul_kernel_optimized<<<numBlocks, threadsPerBlock>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N);

    return C;
}
"""

